"""Build resource bundle only; both executable programs are compiled RF2."""
from pathlib import Path
import subprocess,plistlib,shutil,struct,sys
R=Path(__file__).resolve().parents[1];out=Path(sys.argv[1]);runtime=Path(sys.argv[2]);compiler=Path(sys.argv[3]);app=out/'RiverFlow Studio.app';contents=app/'Contents';mac=contents/'MacOS';resources=contents/'Resources';mac.mkdir(parents=True);resources.mkdir()
subprocess.run([compiler,R/'native/studio/launcher.rf2',mac/'RF2Studio'],check=True,capture_output=True);subprocess.run(['/usr/bin/codesign','-s','-',mac/'RF2Studio'],check=True,capture_output=True);shutil.copy2(runtime,resources/'rf2')
icon=out/'icon1024.png';subprocess.run(['/usr/bin/sips','-z','1024','1024',R/'site/assets/riverflow-mark.png','--out',icon],check=True,capture_output=True);png=icon.read_bytes();(resources/'RiverFlow.icns').write_bytes(struct.pack('>4sI',b'icns',16+len(png))+struct.pack('>4sI',b'ic10',8+len(png))+png)
info={'CFBundleName':'RiverFlow Studio','CFBundleDisplayName':'RiverFlow Studio','CFBundleIdentifier':'com.starkfiber.riverflow.studio','CFBundleExecutable':'RF2Studio','CFBundlePackageType':'APPL','CFBundleShortVersionString':'0.16.0','CFBundleVersion':'16','CFBundleIconFile':'RiverFlow.icns','LSMinimumSystemVersion':'14.0','LSUIElement':True,'NSHighResolutionCapable':True,'NSHumanReadableCopyright':'Ilangkhumanan Thirunavokkarasu · SFE · MIT'}
(contents/'Info.plist').write_bytes(plistlib.dumps(info));subprocess.run(['/usr/bin/codesign','-s','-','--force',app],check=True,capture_output=True);subprocess.run(['/usr/bin/codesign','--verify','--deep','--strict',app],check=True,capture_output=True);print(app)
